132	        LocalDate claimDate = date != null ? date : sheet.defaultClaimDate();
133	        int terms = termsOf(sheet, person, claimDate);
134	        LocalDate dueBy = holidays.dueBy(sheetId, claimDate, terms);
135	        refuseIfClosed(sheetId, dueBy);
136	        refuseIfRetired(person, claimDate);
137	        refuseUnlessCorrects(sheetId, personId, amount, corrects);
138	        String reference = refOf(ref);
