140	            throw refUsed(reference);
141	        }
142	        Rollup.Figures before = rollup.of(sheetId);
143	        Claim claim = new Claim(sheetId, personId, scaled(amount), claimDate, dueBy, noteOf(note), corrects,
144	                claims.lastListed(sheetId) + 1);
145	        claim.setTerms(terms);
146	        boolean late = periods.existsBySheetIdAndSoftClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(
147	                sheetId, dueBy, dueBy);
