156	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_ADDED", user, person, added, added.getNumber())
157	                + (reference == null ? "" : " ref=" + reference) + (tagged == null ? "" : " tags=" + tagged));
158	        if (late) {
159	            audit.recordChangeOnCommit(sheetId, user, entry("LATE_ENTRY", user, person, added, null));
160	        }
161	        rollup.recordChanges(sheetId, user, before);
162	        return added;
163	    }
