242	    /** Move a claim to a new status, as {@link #changeStatus(String, String, long, ClaimStatus)}; a void gives
243	     *  {@code reason} (none when null or blank). While the sheet's list of void reasons is not empty, a void needs a
244	     *  reason on it; the claim keeps the reason and the audit line ends with it. */
245	    @Transactional
246	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason) {
247	        sheets.load(sheetId, user);
248	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
249	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
250	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
251	        refuseIfClosed(sheetId, claim.getDueBy());
252	        if (!claim.getStatus().canBecome(next)) {
253	            throw new ResponseStatusException(HttpStatus.CONFLICT,
254	                    "A " + claim.getStatus() + " claim cannot become " + next);
255	        }
256	        String action = switch (next) {
257	            case OPEN -> "open";
258	            case SETTLED -> "settle";
259	            case VOID -> "void";
260	            default -> null;
261	        };
262	        if (action != null && !sheet.allows(action, roles.roleOf(sheetId, user))) {
263	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim");
264	        }
265	        if (next == ClaimStatus.DRAFT && !sheet.getToday().equals(claim.deletedOn())) {
266	            throw new ResponseStatusException(HttpStatus.CONFLICT,
267	                    "A deleted claim can be restored only on the day it was deleted");
268	        }
269	        boolean voidsSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
270	        if (voidsSettled) {
271	            refuseSettledVoid(sheet, user, claim);
272	        }
273	        String voidReason = next == ClaimStatus.VOID ? voidReasons.refuseUnlisted(sheetId, reason) : null;
274	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheet.getToday())) {
275	            throw new ResponseStatusException(HttpStatus.CONFLICT,
276	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
277	        }
278	        if (next == ClaimStatus.SETTLED && claim.isOpenedOrEditedBy(user)) {
279	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
280	                    "The user who opened or last edited a claim cannot settle it");
281	        }
282	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
283	        BigDecimal due = dueNow(sheet, claim, person);
284	        if (next == ClaimStatus.SETTLED) {
285	            refuseUnproven(sheet, claim, person, due);
286	        } else if (next == ClaimStatus.OPEN) {
287	            refuseUnnoted(sheet, claim, due);
288	            refuseOverCap(sheetId, claim);
289	        }
290	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheet, user, due)) {
291	            next = ClaimStatus.PENDING;
292	        }
293	        Rollup.Figures before = rollup.of(sheetId);
294	        String number = claim.getNumber();
295	        claim.setStatus(next);
296	        if (next == ClaimStatus.OPEN) {
297	            number = nextNumber(sheet, claim.getDueBy());
298	            claim.setNumber(number);
299	            claim.setOpenedBy(user);
300	        } else if (next == ClaimStatus.SETTLED) {
301	            claim.setSettledDue(due);
302	        } else if (next == ClaimStatus.VOID) {
303	            claim.setVoidReason(voidReason);
304	        }
305	        claim.logStatus(user, sheet.getToday(), shownDue(sheet, claim, person));
306	        Claim changed = claims.saveAndFlush(claim);
307	        String event = switch (next) {
308	            case OPEN -> "CLAIM_OPENED";
309	            case PENDING -> "CLAIM_PENDING";
310	            case SETTLED -> "CLAIM_SETTLED";
311	            case VOID -> "CLAIM_VOIDED";
312	            case DELETED -> "CLAIM_DELETED";
313	            case DRAFT -> "CLAIM_RESTORED";
314	        };
315	        String line = entry(event, user, person, changed, number);
316	        if (next == ClaimStatus.SETTLED) {
317	            line += " due=" + dueText(changed);
318	        } else if (voidsSettled) {
319	            line += " reversed=" + dueText(changed);
320	        }
321	        if (voidReason != null) {
322	            line += " reason=" + voidReason;
323	        }
324	        audit.recordChangeOnCommit(sheetId, user, line);
325	        if (next == ClaimStatus.SETTLED) {
326	            watches.notifyWatchers(sheetId, user, person, number);
327	        }
328	        rollup.recordChanges(sheetId, user, before);
329	        return changed;
330	    }
