332	    /** Settle every claim given, one at a time in the order given, by exactly the rules of settling one claim (a
333	     *  claim a clerk's limit makes PENDING counts as settled), as the sheet's next settle batch, each keeping its
334	     *  number; after the claims' own lines BATCH_SETTLED is recorded with the batch's count and the frozen figures
335	     *  of those SETTLED added up. All or nothing: when any claim cannot be settled, none is, nothing is written and
336	     *  null is returned. The claims, as saved, in the order given; none when none is given. */
337	    @Transactional
338	    public List<Claim> settleBatch(String sheetId, String user, List<Long> ids) {
339	        if (ids.isEmpty()) {
340	            return List.of();
341	        }
342	        for (long id : ids) {
343	            try {
344	                changeStatus(sheetId, user, id, ClaimStatus.SETTLED);
345	            } catch (ResponseStatusException refusal) {
346	                TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
347	                return null;
348	            }
349	        }
350	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
351	        int batch = sheet.nextSettleBatch();
352	        sheetStore.saveAndFlush(sheet);
353	        List<Claim> marked = ids.stream().map(id -> {
354	            Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
355	            claim.setSettleBatch(batch);
356	            return claims.saveAndFlush(claim);
357	        }).toList();
358	        BigDecimal total = marked.stream()
359	                .filter(claim -> claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null)
360	                .map(Claim::getSettledDue)
361	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
362	        audit.recordChangeOnCommit(sheetId, user, "BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
363	                + " count=" + marked.size() + " total=" + total.toPlainString());
364	        return marked;
365	    }
