393	    /** A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed, and with it its period and its
394	     *  number, and a figure a statement binds it to stays bound. Refused for anyone but a steward, a claim in any
395	     *  other status, a claim due by inside a closed period and a new date after its person retired. */
396	    @Transactional
397	    public Claim redate(String sheetId, String user, long id, LocalDate date) {
398	        sheets.load(sheetId, user);
399	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
400	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
401	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
402	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
403	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-dates a claim");
404	        }
405	        if (!claim.getStatus().isOpen()) {
406	            throw new ResponseStatusException(HttpStatus.CONFLICT,
407	                    "A " + claim.getStatus() + " claim cannot be re-dated; only an OPEN or PENDING one can");
408	        }
409	        refuseIfClosed(sheetId, claim.getDueBy());
410	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
411	        refuseIfRetired(person, date);
412	        Rollup.Figures before = rollup.of(sheetId);
413	        LocalDate old = claim.getDate();
414	        claim.setDate(date);
415	        Claim redated = claims.saveAndFlush(claim);
416	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_REDATED", user, person, redated, redated.getNumber())
417	                + " old=" + old + " new=" + date);
418	        rollup.recordChanges(sheetId, user, before);
419	        return redated;
