441	    /** Cancel this user's claim editor, releasing their lock on the claim; another user's lock is left as it is. */
442	    @Transactional
443	    public Claim unlock(String sheetId, String user, long id) {
444	        sheets.load(sheetId, user);
445	        sheetStore.findLockedById(sheetId).orElseThrow();
446	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
447	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
448	        if (user.equals(claim.getLockedBy())) {
449	            claim.setLockedBy(null);
