654	    /** Move a claim as {@link #reassign(String, String, long, long)} does, except that a bulk move also takes a
655	     *  claim already of the person it is moved to (it is listed again as that person's newest). */
656	    @Transactional
657	    public Claim reassign(String sheetId, String user, long id, long toPersonId, boolean bulk) {
658	        sheets.load(sheetId, user);
659	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
660	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
661	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
662	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
663	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
664	        if (!sheet.allows("reassign", roles.roleOf(sheetId, user))) {
665	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim");
666	        }
667	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
668	            throw new ResponseStatusException(HttpStatus.CONFLICT,
669	                    "A " + claim.getStatus() + " claim cannot be reassigned");
670	        }
671	        if (!bulk && claim.getPersonId().equals(to.getId())) {
672	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already " + to.getName() + "'s");
673	        }
674	        refuseIfClosed(sheetId, claim.getDueBy());
675	        refuseIfRetired(to, claim.getDate());
676	        refuseUnlessCorrects(sheetId, to.getId(), claim.getAmount(), claim.getCorrects());
677	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
678	        Rollup.Figures before = rollup.of(sheetId);
