802	    /** The next number for a claim due by this day, opened now: within its period (<period name>-<n>, or X-<n>
803	     *  in no period) while the sheet's period numbering is on by its today, else the next number in the sheet-wide
804	     *  sequence its tree shares within the fiscal year of the day (FY<year>-<n>, counting from 1 each year). */
805	    private String nextNumber(Sheet sheet, LocalDate date) {
806	        if (!sheet.numbersPerPeriod()) {
807	            int year = sheet.fiscalYearOf(date);
808	            int last = lastNumberInTree(sheet, year);
809	            ClaimFiscalSequence sequence = fiscalSequences.findBySheetIdAndFiscalYear(sheet.getId(), year)
810	                    .orElseGet(() -> new ClaimFiscalSequence(sheet.getId(), year));
811	            String number = sequence.nextAfter(last);
812	            fiscalSequences.save(sequence);
813	            return number;
814	        }
815	        String prefix = prefixOn(sheet, date);
816	        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(sheet.getId(), prefix)
817	                .orElseGet(() -> new ClaimSequence(sheet.getId(), prefix));
818	        String number = sequence.next();
819	        sequences.save(sequence);
820	        return number;
821	    }
822	
823	    /** The last sheet-wide number given in a fiscal year anywhere in the sheet's tree but the sheet itself: the
824	     *  sheet at the top of its line of parents and all of that sheet's descendants. The top sheet is locked so the
825	     *  tree's numbers are given one at a time. */
826	    private int lastNumberInTree(Sheet sheet, int fiscalYear) {
827	        List<String> ancestors = sheetStore.ancestorsOf(sheet.getId(), Integer.MAX_VALUE);
828	        String top = ancestors.isEmpty() ? sheet.getId() : ancestors.get(ancestors.size() - 1);
829	        if (!top.equals(sheet.getId())) {
830	            sheetStore.findLockedById(top);
831	        }
832	        Set<String> others = new HashSet<>(sheetStore.descendantsOf(top));
833	        others.add(top);
834	        others.remove(sheet.getId());
835	        return others.isEmpty() ? 0 : fiscalSequences.lastNumberOf(others, fiscalYear);
836	    }
