855	     *  with no due, or on a sheet with no threshold then, needs none). */
856	    private static void refuseUnnoted(Sheet sheet, Claim claim, BigDecimal due) {
857	        BigDecimal threshold = sheet.noteThresholdOn(claim.getDate());
858	        if ((claim.getNote() == null || claim.getNote().isBlank()) && threshold != null && due != null
859	                && due.compareTo(threshold) > 0) {
860	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
861	                    "A claim whose due is above the note threshold of " + threshold + " needs a note first");
862	        }
